import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { DataSource } from 'typeorm';

interface CdrPayload {
  cdrId: string;
  subscriberMsisdn: string;
  warrantToken?: string;
}

@Controller()
export class CdrMicroserviceController {
  constructor(private dataSource: DataSource) {}

  @MessagePattern({ service: 'telecom', cmd: 'get_call_record' })
  async getCdr(@Payload() data: CdrPayload) {
    if (!data.subscriberMsisdn && !data.warrantToken) {
      return { error: 'Subscriber authentication or valid warrant token required', status: 401 };
    }

    // Verify either ownership of caller MSISDN or valid compliance token
    let query = 'SELECT id, origin_msisdn, destination_msisdn, duration_seconds, cell_tower_id, gps_latitude, gps_longitude FROM call_records WHERE id = $1';
    let params: any[] = [data.cdrId];

    if (!data.warrantToken) {
      query += ' AND (origin_msisdn = $2 OR destination_msisdn = $2)';
      params.push(data.subscriberMsisdn);
    }

    const [record] = await this.dataSource.query(query, params);

    if (!record) {
      return { error: 'Record not found or access unauthorized', status: 403 };
    }

    return record;
  }
}
